// src/schemas/auth-tokens/account-token-indexes.ts
/** Build the shared indexes, named with the table's prefix. */
function accountTokenIndexes(builders, prefix, t) {
	return [
		builders.uniqueIndex(`${prefix}_identifier_token_hash_unique`).on(t.identifier, t.tokenHash),
		builders.index(`${prefix}_user_id_idx`).on(t.userId),
		builders.index(`${prefix}_expires_idx`).on(t.expires),
		builders.index(`${prefix}_token_hash_idx`).on(t.tokenHash)
	];
}
export { accountTokenIndexes as t };
